window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[84]={"id":"084","numero":84,"titre":"Glaucome chronique","objectifs":[{"id":"84-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du glaucome primitif à angle ouvert","contenu":"<p>Le <span class=\"kw-def\">glaucome primitif à angle ouvert (GPAO)</span> est une <strong>neuropathie optique progressive</strong> caractérisée par une <strong>apoptose accélérée des cellules ganglionnaires rétiniennes</strong> (qui constituent le nerf optique), survenant en présence d'un <strong>angle iridocornéen ouvert</strong> et en l'absence d'anomalies oculaires ou générales identifiables.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Double atteinte caractéristique ⭐</h4>\n      <table >\n        <thead><tr><th>Versant</th><th>Traduction</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Structurel</span></strong></td>\n            <td>Anomalies caractéristiques de la <strong>tête du nerf optique</strong> (papille optique) — diminution de l'anneau neurorétinien, augmentation du <em>cup/disc ratio</em>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Fonctionnel</span></strong></td>\n            <td>Altérations du <strong>champ visuel</strong> pouvant aboutir à la <span class=\"kw-alerte\">cécité</span> à un <span class=\"kw-def\">stade</span> tardif.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification</span> des glaucomes</h4>\n      <table >\n        <thead><tr><th>Critère</th><th>Sous-types</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Selon l'angle iridocornéen</strong></td>\n            <td>\n              <strong>Angle ouvert :</strong> iris et cornée largement écartés → humeur aqueuse accède au trabéculum<br>\n              <strong>Angle fermé :</strong> iris s'appose contre le trabéculum et la cornée, empêchant l'accès de l'humeur aqueuse\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Selon l'étiologie</strong></td>\n            <td>\n              <strong>Primitif :</strong> aucune anomalie oculaire ou générale associée<br>\n              <strong>Secondaire :</strong> lié à une autre pathologie oculaire ou générale\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Répartition géographique.</strong> En Occident et en Afrique, le <span class=\"kw-chiffre\">GPAO représente 70-80 %</span> de l'ensemble des glaucomes. En Asie, <span class=\"kw-clinique\">les</span> <strong>glaucomes par fermeture de l'angle</strong> prédominent.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Altération chronique de la vision · 82 — Anomalie aiguë de la vision</em></p>","frequence":0},{"id":"84-2","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principes de mesure de la pression intra-oculaire, en relation avec l’épaisseur cornéenne","contenu":"<p>La <span class=\"kw-def\">pression intra-oculaire (PIO)</span> est le seul <span class=\"kw-def\">facteur de risque</span> <strong>modifiable</strong> du GPAO. Sa mesure est <strong>indispensable</strong> à toute consultation ophtalmologique au-delà de <span class=\"kw-chiffre\">40 ans</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Valeurs de référence</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><strong>PIO normale moyenne</strong></td><td><span class=\"kw-chiffre\">15,5 mmHg</span> (écart type <span class=\"kw-chiffre\">2,5 mmHg</span>)</td></tr>\n          <tr><td><strong>Seuil supérieur statistique</strong></td><td><span class=\"kw-chiffre\">&gt; 20-22 mmHg</span> (2 écarts types au-dessus de la moyenne)</td></tr>\n          <tr><td><strong>Seuil de crise aiguë</strong></td><td><span class=\"kw-alerte\">&gt; 30 mmHg</span> avec sensation de « bille de bois » à la palpation</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Influence de l'épaisseur cornéenne centrale (ECC) ⭐</h4>\n      <table >\n        <thead><tr><th>Épaisseur cornéenne</th><th>Effet sur la PIO mesurée</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cornée fine</strong></td>\n            <td>PIO mesurée <strong>sous-estimée</strong></td>\n            <td>Risque de méconnaître une vraie hypertonie</td>\n          </tr>\n          <tr>\n            <td><strong>Cornée épaisse</strong></td>\n            <td>PIO mesurée <strong>surestimée</strong></td>\n            <td>Risque de surdiagnostic d'hypertonie</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Gonioscopie</h4>\n      <p>La <span class=\"kw-def\">gonioscopie</span> est l'examen de l'<strong>angle iridocornéen</strong>, réalisé à la lampe à fente à l'aide d'un verre de <span class=\"kw-def\">contact</span> comportant un miroir. Elle permet de classer le glaucome selon que l'angle est ouvert ou fermé.</p>\n      <table >\n        <thead><tr><th>Résultat</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Normal</strong></td><td>Trabéculum p<span class=\"kw-chiffre\">igm</span>enté visible sur <strong>&gt; 180°</strong> de la circonférence → angle ouvert</td></tr>\n          <tr><td><strong>Ouvert avec néovascularisation</strong></td><td>Glaucome néovasculaire (<span class=\"kw-def\">diabète</span>, OACR, OVCR <span class=\"kw-etio\">ischémique</span>)</td></tr>\n          <tr><td><strong>Fermé</strong></td><td>Trabéculum non visible → crise aiguë par fermeture de l'angle</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <strong>PIO normale n'élimine pas un GPAO</strong> : le <em>glaucome à pression normale</em> est une forme reconnue. Inversement, une PIO élevée isolée sans neuropathie = <strong>hypertonie oculaire</strong>, qui touche <span class=\"kw-chiffre\">10x plus</span> de patients que le glaucome.\n      </div>","frequence":1},{"id":"84-3","rang":"A","rubrique":"Définition","titre":"Connaître les facteurs de risque du glaucome primitif à angle ouvert","contenu":"<p>Six <span class=\"kw-def\">facteurs de risque</span> <strong>indépendants</strong> sont reconnus pour le GPAO. L'<strong>âge</strong>, l'<strong>hypertonie oculaire</strong>, <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-etio\">antécédents familiaux</span></strong>, l'<strong>ethnie mélanoderme</strong> et la <strong>myopie</strong> sont les plus établis ; <span class=\"kw-def\">diabète</span> et maladies <span class=\"kw-bio\">CV</span> sont moins bien étayés.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Facteurs de risque</span> majeurs</h4>\n      <table >\n        <thead><tr><th>Facteur</th><th>Quantification du risque</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge élevé</strong></td>\n            <td><span class=\"kw-def\">Prévalence</span> <span class=\"kw-chiffre\">&lt; 0,5 %</span> entre <span class=\"kw-chiffre\">40-50 ans</span> → <span class=\"kw-chiffre\">≈ 10 %</span> après <span class=\"kw-chiffre\">85 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hypertonie oculaire</strong></td>\n            <td>PIO <span class=\"kw-chiffre\">&gt; 20-22 mmHg</span> = FR <strong>mais non obl<span class=\"kw-chiffre\">iga</span>toire pour le diagnostic</strong> ❌</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD familiaux directs</strong></td>\n            <td>Risque <span class=\"kw-chiffre\">×3</span> chez <span class=\"kw-clinique\">les</span> descendants (gènes identifiés mais sans application clinique)</td>\n          </tr>\n          <tr>\n            <td><strong>Ethnie mélanoderme</strong></td>\n            <td>Noirs d'origine africaine : risque <span class=\"kw-chiffre\">×3</span></td>\n          </tr>\n          <tr>\n            <td><strong>Myopie</strong></td>\n            <td>Toute intensité de myopie : risque <span class=\"kw-chiffre\">×3</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diabète</span>, maladies <span class=\"kw-bio\">CV</span></strong></td>\n            <td>FR décrits mais <em>moins bien étayés</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'hypertonie oculaire est le <strong>seul FR modifiable</strong> et donc la cible thérapeutique exclusive. Mais sa <em>présence n'est ni nécessaire ni suffisante</em> pour porter le diagnostic de GPAO.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-def\">Diabète</span> · 81 — Altération chronique de la vision</em></p>","frequence":0},{"id":"84-4","rang":"B","rubrique":"Physiopathologie","titre":"Savoir que le glaucome primitif à angle ouvert est une perte accélérée des fibres optiques avec apoptose","contenu":"<p>Le GPAO est une <span class=\"kw-def\">maladie neurodégénérative</span> caractérisée par une <strong>accélération de l'apoptose physiologique</strong> des cellules ganglionnaires rétiniennes — fibres qui constituent le nerf optique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Rappel anatomo-fonctionnel</h4>\n      <ul>\n        <li>Chaque œil contient environ <span class=\"kw-chiffre\">1 million</span> de cellules ganglionnaires rétiniennes.</li>\n        <li>Ces cellules transmettent l'information visuelle des photorécepteurs aux cellules bipolaires, puis au <strong>corps genouillé latéral</strong>.</li>\n        <li>Après <span class=\"kw-chiffre\">40 ans</span>, le vieillissement physiologique entraîne la perte de <span class=\"kw-chiffre\">5 000 à 8 000 cellules ganglionnaires/an</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pathogenèse</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Accélération apoptotique</strong></td>\n            <td>Le GPAO multiplie la vitesse de perte des cellules ganglionnaires au-delà de la cinétique physiologique liée à l'âge.</td>\n          </tr>\n          <tr>\n            <td><strong>2. Atteinte structurelle</strong></td>\n            <td>Diminution de l'anneau neurorétinien → <strong>excavation papillaire</strong> progressive (cup/disc ratio croissant).</td>\n          </tr>\n          <tr>\n            <td><strong>3. Atteinte fonctionnelle</strong></td>\n            <td>Apparition de <span class=\"kw-clinique\">scotomes</span> en champ visuel (initialement périphériques, sans BAV) → <strong>champ tubulaire</strong> aux stades avancés.</td>\n          </tr>\n          <tr>\n            <td><strong>4. Cécité</strong></td>\n            <td>BAV centrale tardive, <span class=\"kw-alerte\">irréversible</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Conséquence clinique.</strong> Le GPAO est <em>initialement asymptomatique</em> et d'<span class=\"kw-clinique\">évolution</span> lente (au contraire du GAFA). C'est ce qui fait toute sa gravité : altérations du champ visuel <strong>périphérique</strong> d'abord, BAV uniquement aux stades tardifs.\n      </div>","frequence":1},{"id":"84-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les deux formes cliniques de glaucome primitif à angle ouvert : à pression intra-oculaire (PIO) élevée et PIO normale","contenu":"<p>Le GPAO se décline en <strong>deux formes cliniques</strong> distinguées par le niveau de PIO — mais la prise en charge reste identique (<span class=\"kw-ttt\">réduction</span> de la PIO).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Les</span> 2 formes de GPAO</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Fréquence (Occident)</th><th>PIO</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>GPAO à PIO élevée</strong></td>\n            <td><span class=\"kw-chiffre\">70-80 %</span> des GPAO</td>\n            <td>PIO &gt;<span class=\"kw-chiffre\"> 20-22 mmHg</span></td>\n            <td>Forme « classique », hypertonie détectée à la mesure</td>\n          </tr>\n          <tr>\n            <td><strong>GPAO à pression normale</strong> ⭐</td>\n            <td><span class=\"kw-chiffre\">20-30 %</span> des GPAO</td>\n            <td>PIO dans <span class=\"kw-clinique\">les</span> limites de la normale</td>\n            <td>Neuropathie optique + altérations champ visuel <strong>sans</strong> hypertonie</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Implication thérapeutique.</strong> Dans <span class=\"kw-clinique\">les</span> <strong>2 formes</strong>, le seul facteur accessible au traitement reste la <strong>PIO</strong>. On baisse donc la PIO <em>même</em> dans le glaucome à pression normale — l'objectif est de descendre <strong>en deçà</strong> du niveau initial, qui s'avère « trop élevé » pour le nerf optique du patient.\n      </div>\n\n      <p>Le bilan clinique et paraclinique est <strong>identique</strong> dans <span class=\"kw-clinique\">les</span> 2 formes : <span class=\"kw-imagerie\">FO</span> + <span class=\"kw-imagerie\">OCT</span> + champ visuel. La gonioscopie confirme l'angle ouvert dans les 2 cas.</p>","frequence":0},{"id":"84-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales caractéristiques de l’atteinte du glaucome primitif à angle ouvert : structure et fonction","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> de GPAO repose sur la <strong>combinaison</strong> d'anomalies <span class=\"kw-def\">structurelles</span> (papille, <span class=\"kw-imagerie\">OCT</span>) et <span class=\"kw-def\">fonctionnelles</span> (champ visuel). <span class=\"kw-clinique\">Les</span> anomalies de structure <strong>précèdent</strong> souvent les anomalies fonctionnelles.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Aspect clinique global</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>GPAO</th></tr></thead>\n        <tbody>\n          <tr><td>Aspect externe</td><td><strong>Œil blanc, indolore</strong> ⭐ — aucune rougeur, aucune douleur</td></tr>\n          <tr><td>Acuité visuelle</td><td><strong>Non affectée</strong> ⭐ — BAV uniquement aux stades tardifs</td></tr>\n          <tr><td>Pupille</td><td>Motilité normale ; déficit pupillaire afférent relatif au <span class=\"kw-def\">stade</span> tardif</td></tr>\n          <tr><td>Examen LAF</td><td>Chambre antérieure <strong>profonde</strong></td></tr>\n          <tr><td>Gonioscopie</td><td>Angle <strong>ouvert</strong> (trabéculum visible sur &gt; 180°)</td></tr>\n          <tr><td>PIO</td><td>Élevée (<span class=\"kw-chiffre\">70-80 %</span> des cas) ou <strong>normale</strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Atteinte structurelle — <span class=\"kw-imagerie\">fond d'œil</span> + <span class=\"kw-imagerie\">OCT</span></h4>\n      <p>Anomalies de la <strong>papille optique</strong> (tête du nerf optique = coudure à 90° des axones avant le canal scléral) :</p>\n      <ul>\n        <li><strong>Diminution de la surface de l'anneau neurorétinien</strong> (diffuse ou localisée).</li>\n        <li><strong>Hémorragies parapapillaires en flammèches.</strong></li>\n        <li><strong>Atrophie parapapillaire de type bêta.</strong></li>\n        <li><strong>Augmentation de l'excavation papillaire</strong> (rapport <em>cup/disc</em>) :\n          <ul>\n            <li><em>Disc</em> = <span class=\"kw-clinique\">diamètre</span> total de la papille ; <em>Cup</em> = zone centrale plus blanche (sans fibres optiques).</li>\n            <li>Suspect de glaucome si : <strong><span class=\"kw-clinique\">asymétrie</span> cup/disc &gt; 0,2 entre <span class=\"kw-clinique\">les</span> 2 yeux</strong> (collège) ou <strong>cup/disc &gt; 0,6</strong> (abrégé).</li>\n            <li>Photographies de papille recommandées pour documenter la <em>progression</em>.</li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-imagerie\">OCT</span></strong> : quantifie surfaces et volumes — utile au <span class=\"kw-def\">diagnostic positif</span>, différentiel, <span class=\"kw-def\">suivi</span> et évaluation thérapeutique.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Atteinte fonctionnelle — champ visuel ⭐</h4>\n      <p>Examen clé = <strong>périmétrie statique automatisée de Humphrey (<span class=\"kw-bio\">PSA</span>)</strong>. ⚠️ À ne pas confondre avec la périmétrie cinétique de Goldmann.</p>\n      <table >\n        <thead><tr><th>Anomalie</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Scotome arciforme de Bjerrum</strong> ++ ⭐</td>\n            <td>Part de la <strong>tache aveugle</strong> et <strong>contourne</strong> le point de fixation central</td>\n          </tr>\n          <tr>\n            <td><strong>Ressaut nasal</strong></td>\n            <td>Ressaut à la limite du champ visuel <strong>nasal</strong>, au niveau du <strong>méridien horizontal</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Déficits scotomateux paracentraux</strong></td>\n            <td>Isolés, relatifs et absolus</td>\n          </tr>\n          <tr>\n            <td><strong>Scotome tubulaire</strong></td>\n            <td><span class=\"kw-def\">Stade</span> avancé — précède la <span class=\"kw-alerte\">cécité</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Circonstances de découverte.</strong> Le GPAO est typiquement découvert <em>fortuitement</em> lors d'une consultation ophtalmo de routine (PIO &gt;<span class=\"kw-chiffre\"> 21 mmHg</span>, excavation papillaire), ou suite à des <strong>ATCD familiaux</strong>. Découverte sur BAV = <strong>GPAO très avancé</strong>, atteinte hélas irréversible. Une BAV plus rapide peut révéler une <strong>occlusion veineuse rétinienne</strong>, dont le GPAO est un FR.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 81 — Altération chronique de la vision</em></p>","frequence":1},{"id":"84-7","rang":"A","rubrique":"Prise en charge","titre":"Savoir que le traitement du glaucome primitif à angle ouvert est la réduction de la PIO","contenu":"<p>L'objectif thérapeutique du GPAO est <strong>univoque</strong> : <span class=\"kw-def\">réduire la PIO</span> pour ralentir la dégénérescence des fibres optiques. La PIO est <strong>le seul <span class=\"kw-def\">facteur de risque</span> accessible au traitement</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Principes fondamentaux</h4>\n      <table >\n        <thead><tr><th>Principe</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>Stopper l'<span class=\"kw-clinique\">évolution</span> de la neuropathie en baissant la PIO en dessous de sa valeur jugée « <span class=\"kw-etio\">toxique</span> » pour le nerf optique</td>\n          </tr>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td>S'applique <strong>aussi bien</strong> au GPAO à PIO élevée qu'au GPAO à PIO normale</td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>Traitement hypotonisant <strong>à vie</strong> ⭐ — ne doit pas être interrompu inopinément</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span> sans traitement</strong></td>\n            <td>Dégradation progressive et <span class=\"kw-alerte\">irréversible</span> du champ visuel → <strong>champ tubulaire</strong> → cécité</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Hiérarchie thérapeutique</h4>\n      <ol>\n        <li><strong><span class=\"kw-chiffre\">1ère intention</span> :</strong> monothérapie en collyre — analogue de prostaglandine OU β-bloquant.</li>\n        <li><strong>2ème intention :</strong> bithérapie en combinant <span class=\"kw-clinique\">les</span> 4 classes disponibles (toutes associations possibles).</li>\n        <li><strong>3ème intention :</strong> <span class=\"kw-ttt\">chirurgie</span> filtrante (trabéculectomie de référence) ou sclérectomie profonde.</li>\n        <li><strong>Option intermédiaire :</strong> trabéculoplastie au <span class=\"kw-ttt\">laser</span> Argon (effet modeste et peu durable).</li>\n      </ol>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Suivi</span>.</strong> Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> : PIO, aspect de la tête du nerf optique (<span class=\"kw-imagerie\">FO</span>, <span class=\"kw-imagerie\">OCT</span>) et champ visuel. Le traitement est <em>modifié</em> en cas d'aggravation trop rapide des altérations.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège invalidité.</strong> Le handicap du glaucomateux est causé par l'<strong>altération du champ visuel</strong>, <em>jamais</em> par la baisse d'acuité visuelle. La grille d'invalidité pertinente est celle <strong>en fonction du champ visuel</strong>, pas celle de l'AV.\n      </div>","frequence":0},{"id":"84-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les différentes classes thérapeutiques d’anti-hypertenseurs oculaires, leurs contre-indications et leurs effets secondaires","contenu":"<p>Quatre <strong>classes principales</strong> de collyres hypotonisants, classées selon le mécanisme : <em>augmentation de l'élimination</em> ou <em>diminution de la sécrétion</em> d'humeur aqueuse. La prescription s'adapte aux <strong>CI</strong> et <strong>EI</strong> de chaque classe.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Tableau récapitulatif des 4 classes ⭐⭐</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Posologie</th><th>Effets indésirables</th><th><span class=\"kw-ci\">Contre-indications</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Analogues de prostaglandines</span></strong><br><em>(souvent <span class=\"kw-chiffre\">1ère intention</span>)</em></td>\n            <td><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>outte le <strong>soir</strong></td>\n            <td>\n              <strong>Rougeur, irritation</strong> ; <br>\n              <strong>Hyperp<span class=\"kw-chiffre\">igm</span>entation irienne</strong> ; <br>\n              <strong>Allongement des cils</strong> ; <br>\n              Tolérance générale excellente\n            </td>\n            <td>Peu de CI systémiques</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">β-bloquants en collyre</span></strong><br><em>(souvent <span class=\"kw-chiffre\">1ère intention</span>)</em></td>\n            <td><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>outte <strong>matin + soir</strong> (formes LP : 1×/j)</td>\n            <td>Mêmes EI que β-bloquants systémiques (passage systémique)</td>\n            <td>\n              <span class=\"kw-ci\">Asthme</span> ; <br>\n              <span class=\"kw-ci\">Insuffisance cardiaque</span> ; <br>\n              <span class=\"kw-ci\">Troubles de conduction</span> ; <br>\n              <span class=\"kw-ci\">Phénomène de Raynaud</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Agonistes α2-adrénergiques</span></strong><br><em>(brimonidine — 2nde intention)</em></td>\n            <td><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>outte matin + soir</td>\n            <td>Sécheresse buccale, somnolence, <span class=\"kw-ci\">allergie</span> locale</td>\n            <td><span class=\"kw-ttt\">IMAO</span>, enfant &lt;<span class=\"kw-chiffre\"> 2 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Inhibiteurs de l'anhydrase carbonique</span></strong><br><em>(brinzolamide, dorzolamide en collyre)</em></td>\n            <td><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>outte matin + soir</td>\n            <td>Goût amer, irritation locale</td>\n            <td><span class=\"kw-ci\">Allergie</span> aux <span class=\"kw-ttt\">sulfamides</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Acétazolamide (voie générale) — cas particulier</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td>Cas précis, rarement au long cours — le plus souvent <strong>en attente d'un traitement chirurgical</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Voie</strong></td>\n            <td>Per os ou IV, en association au traitement local</td>\n          </tr>\n          <tr>\n            <td><strong>Effets secondaires fréquents et invalidants</strong></td>\n            <td>\n              <strong>Acidose métabolique</strong> ; <br>\n              <strong>Hypokaliémie</strong> ; <br>\n              <strong>Lithiase rénale</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Contre-indications</span></strong></td>\n            <td>\n              <span class=\"kw-ci\">Insuffisance rénale</span> ; <br>\n              <span class=\"kw-ci\">Insuffisance hépatique sévère</span> ; <br>\n              <span class=\"kw-ci\">Allergie aux sulfamides</span> ; <br>\n              <span class=\"kw-ci\">Lithiase rénale</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Règle d'association.</strong> On peut associer plusieurs collyres hypotonisants sans dépasser en règle une <strong>« <span class=\"kw-ttt\">trithérapie</span> »</strong>. Certains collyres associent 2 principes actifs en une seule administration pour améliorer l'observance.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ci\">Contre-indications</span> médicamenteuses du GPAO (rang B) ⭐.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">corticoïdes</span> sont la <strong>seule classe</strong> <span class=\"kw-ci\">contre-indiquée</span> car ils peuvent élever la PIO :\n        <ul style=\"margin:6px 0 0;\">\n          <li><strong>Voie locale</strong> (collyres, injection sous-conjonctivale ou intravitréenne) : <span class=\"kw-alerte\">élévation rapide, importante, prolongée</span> de la PIO</li>\n          <li><strong>Voie ORL</strong> : risque réel par proximité oculaire — avis spécialisé</li>\n          <li><strong>Voie générale</strong> : risque faible, retardé — avis si <span class=\"kw-ttt\">corticothérapie</span> prolongée envisagée</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments</em></p>","frequence":2},{"id":"84-9","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’importance du dépistage du glaucome primitif à angle ouvert à 40 ans","contenu":"<p>Le GPAO est une maladie <strong>silencieuse</strong> jusqu'aux stades tardifs : c'est ce qui justifie un <span class=\"kw-def\">dépistage systématique</span> par mesure de la PIO + <span class=\"kw-imagerie\">fond d'œil</span> <strong>chez tout patient de plus de <span class=\"kw-chiffre\">40 ans</span></strong> et/ou en présence de FR.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Modalités du <span class=\"kw-def\">dépistage</span></h4>\n      <table >\n        <thead><tr><th>Cible</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Patient &gt;<span class=\"kw-chiffre\"> 40 ans</span> (population générale)</strong></td>\n            <td>Mesure PIO + examen du <strong><span class=\"kw-imagerie\">fond d'œil</span></strong> lors de toute consultation ophtalmologique</td>\n          </tr>\n          <tr>\n            <td><strong>Sujet à FR (ATCD familiaux, mélanoderme, myope)</strong></td>\n            <td><span class=\"kw-def\">Surveillance</span> ophtalmologique régulière dès <strong><span class=\"kw-chiffre\">40 ans</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Si PIO &gt;<span class=\"kw-chiffre\"> 21 mmHg</span> ou anomalie de papille</strong></td>\n            <td>Bilan complet : <strong>champ visuel + <span class=\"kw-imagerie\">OCT</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pourquoi à<span class=\"kw-chiffre\"> 40 ans</span> ?</h4>\n      <ul>\n        <li><span class=\"kw-def\">Prévalence</span> du GPAO : <span class=\"kw-chiffre\">&lt; 0,5 %</span> entre <span class=\"kw-chiffre\">40-50 ans</span> → <span class=\"kw-chiffre\">~10 %</span> après <span class=\"kw-chiffre\">85 ans</span>.</li>\n        <li>Apparition typique de l'atteinte glaucomateuse <strong>dès <span class=\"kw-chiffre\">40-50 ans</span></strong>.</li>\n        <li>Le GPAO est asymptomatique au début : <strong>seul un <span class=\"kw-def\">dépistage</span> actif</strong> permet une prise en charge précoce.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Poids de santé publique ⭐</h4>\n      <ul>\n        <li><strong>2ème cause de cécité dans le monde</strong> (80-110 millions d'atteints, ~3 millions d'aveugles).</li>\n        <li><strong>2ème cause de cécité en pays occidentaux</strong> (après la DMLA).</li>\n        <li><strong>1ère cause de cécité irréversible</strong> dans le monde.</li>\n        <li>En France : <span class=\"kw-chiffre\">1 à 1,2 million</span> de patients glaucomateux estimés.</li>\n        <li><span class=\"kw-chiffre\">1/10</span> patients glaucomateux présente une cécité légale.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Enjeu.</strong> Le GPAO est une maladie <em>évitable</em> au <span class=\"kw-def\">stade</span> de cécité, à condition d'un <strong><span class=\"kw-def\">dépistage</span> actif</strong> avant l'apparition des symptômes — d'où l'âge-charnière de <strong><span class=\"kw-chiffre\">40 ans</span></strong>.\n      </div>","frequence":0},{"id":"84-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les mécanismes d’action des traitements médicaux","contenu":"<p><span class=\"kw-clinique\">Les</span> traitements médicaux du GPAO agissent selon <strong>deux mécanismes opposés</strong> sur la circulation de l'humeur aqueuse : soit en <strong>augmentant son élimination</strong>, soit en <strong>diminuant sa sécrétion</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Schéma physiologique de l'humeur aqueuse</h4>\n      <ol>\n        <li><strong>Sécrétion</strong> par <span class=\"kw-clinique\">les</span> procès ciliaires (corps ciliaire) en chambre postérieure.</li>\n        <li>Passage en <strong>chambre antérieure</strong> à travers la pupille.</li>\n        <li><strong>Évacuation</strong> par le <strong>trabéculum</strong> dans l'angle iridocornéen → canal de Schlemm → veines épisclérales.</li>\n      </ol>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification</span> des collyres par mécanisme ⭐</h4>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Classes</th><th>Cible physiologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"3\" style=\"vertical-align:top;\"><strong>Augmentation de l'élimination</strong> d'humeur aqueuse</td>\n            <td><span class=\"kw-ttt\">Analogues de prostaglandines</span> (<span class=\"kw-chiffre\">1ère intention</span>)</td>\n            <td>Voie uvéosclérale</td>\n          </tr>\n          <tr>\n            <td><em>Collyres adrénaliniques</em></td>\n            <td>Voie trabéculaire</td>\n          </tr>\n          <tr>\n            <td><em>Collyres myotiques parasympathomimétiques</em> (pilocarpine)</td>\n            <td>Contraction du sphincter irien → ouverture trabéculaire</td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\" style=\"vertical-align:top;\"><strong>Diminution de la sécrétion</strong> d'humeur aqueuse</td>\n            <td><span class=\"kw-ttt\">β-bloquants en collyre</span> (<span class=\"kw-chiffre\">1ère intention</span>)</td>\n            <td>Blocage des récepteurs β au niveau du corps ciliaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Agonistes α2-adrénergiques</span> (brimonidine)</td>\n            <td>Vasoconstriction du corps ciliaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Inhibiteurs de l'anhydrase carbonique</span> (acétazolamide)<br>Voie topique OU générale</td>\n            <td>Inhibition de l'anhydrase carbonique du corps ciliaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Stratégie thérapeutique.</strong> Le choix se fait selon <span class=\"kw-clinique\">les</span> <strong>CI et EI</strong> du patient. En cas d'efficacité insuffisante d'une monothérapie : <strong>switch</strong> avant bithérapie. En cas de bithérapie : combiner deux classes à mécanismes <em>complémentaires</em> (ex. prostaglandine + β-bloquant).\n      </div>","frequence":1},{"id":"84-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement non pharmacologique","contenu":"<p>Au-delà des collyres, le traitement non pharmacologique du GPAO comprend deux niveaux : la <strong>trabéculoplastie au <span class=\"kw-ttt\">laser</span></strong> (option intermédiaire) et la <strong><span class=\"kw-ttt\">chirurgie</span> filtrante</strong> (3ème intention ou indication d'emblée).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Trabéculoplastie au <span class=\"kw-ttt\">laser</span> Argon</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Principe</strong></td>\n            <td>Photocoagulation sélective de l'<strong>angle iridocornéen</strong> au <span class=\"kw-ttt\">laser</span> <strong>Argon</strong> → meilleur écoulement de l'humeur aqueuse au niveau du trabéculum</td>\n          </tr>\n          <tr>\n            <td><strong>Place</strong></td>\n            <td>Entre <span class=\"kw-clinique\">les</span> médicaments et la <span class=\"kw-ttt\">chirurgie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Effet</strong></td>\n            <td>Souvent <strong>modeste</strong> et <strong>non durable</strong> dans le temps</td>\n          </tr>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td>Cas sélectionnés (option thérapeutique alternative)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-ttt\">Chirurgie</span> filtrante</h4>\n      <p>Repose sur la <strong>fistulisation sous-conjonctivale</strong> de l'humeur aqueuse.</p>\n\n      <table >\n        <thead><tr><th>Technique</th><th>Description</th><th>Place</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Trabéculectomie</strong> ⭐<br><em>(procédure de référence)</em></td>\n            <td>Incision conjonctivale → volet scléral lamellaire → <strong>ablation sectorielle limitée du trabéculum</strong> (résection pleine épaisseur mettant l'humeur aqueuse en relation directe avec l'espace sous-conjonctival)</td>\n            <td><span class=\"kw-chiffre\">1ère intention</span> chirurgicale</td>\n          </tr>\n          <tr>\n            <td><strong>Sclérectomie profonde</strong></td>\n            <td><span class=\"kw-ttt\">Exérèse</span> partielle du trabéculum <strong>sans</strong> ouverture du globe oculaire (préservation de la paroi sclérale)</td>\n            <td>Alternative</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Chirurgie</span> micro-invasive (MIGS)</strong></td>\n            <td>Petits drains/tubes — meilleur contrôle du débit, moins de complications, récupération plus rapide. <em>En cours d'évaluation</em>.</td>\n            <td>Émergente</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications de la <span class=\"kw-ttt\">chirurgie</span></h4>\n      <ul>\n        <li>Échec du traitement médical (majorité des cas).</li>\n        <li><span class=\"kw-ci\">Intolérance</span> aux collyres.</li>\n        <li>Recours <em>d'emblée</em> si : <strong>glaucome évolué</strong>, patient <strong>jeune</strong>, coexistence d'une <strong>cataracte</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Complications des chirurgies filtrantes</h4>\n      <ul>\n        <li><strong>Cataracte</strong> secondaire.</li>\n        <li><strong>Hypotonie précoce</strong> compliquée de décollement choroïdien, voire de décollement de rétine → risque de <span class=\"kw-alerte\">phtyse du globe</span> avec cécité définitive.</li>\n        <li><strong>Endophtalmie aiguë</strong> (quelques semaines post-op) — <span class=\"kw-alerte\">urgence</span>.</li>\n        <li><strong>Fibrose de la <span class=\"kw-clinique\">bulle</span> de filtration</strong> → <span class=\"kw-ttt\">reprise chirurgicale</span>.</li>\n        <li><strong>Endophtalmie à distance</strong> (toute conjonctivite <span class=\"kw-etio\">bactérienne</span> peut se transformer en endophtalmie, <em>même des dizaines d'années plus tard</em>).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Échec chirurgical.</strong> La cause principale est la <strong>fibrose sous-conjonctivale</strong>. Patients à haut risque : <strong>jeunes</strong> et <strong>mélanodermes</strong>. Prévention : <strong>antimétabolites</strong> appliqués au site opératoire (mitomycine C, 5-FU).\n      </div>","frequence":1},{"id":"84-12","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d’une crise de glaucome aigu par fermeture de l’angle","contenu":"<p>La <span class=\"kw-def\">crise aiguë par fermeture de l'angle (CAFA)</span>, souvent improprement appelée « glaucome aigu », est une <span class=\"kw-alerte\">urgence ophtalmologique</span> menaçant le <span class=\"kw-def\">pronostic</span> visuel. Tableau d'installation <strong>brutale</strong> et <strong>bruyante</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Triade évocatrice ⭐</h4>\n      <table >\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Œil rouge</span></strong></td>\n            <td>Hyperhémie conjonctivale + <strong>cercle périkératique</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Œil douloureux</span></strong></td>\n            <td>Douleurs <strong>profondes, intenses</strong>, oculaires et péri-oculaires, irradiant dans le territoire du <strong>trijumeau</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">BAV brutale</span></strong></td>\n            <td>Souvent importante — dépend de l'<strong><span class=\"kw-clinique\">œdème</span> cornéen</strong> lié à l'hypertonie</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes associés</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Nausées, vomissements</span> ++ (souvent associés → piège diagnostique abdominal).</li>\n        <li><strong>Pupille en semi-mydriase aréflexique</strong> (traduit le bloc pupillaire).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen ophtalmologique</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Résultat</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cornée</strong></td>\n            <td><strong><span class=\"kw-clinique\">Œdème</span> cornéen</strong> : cornée opaque, reliefs de l'iris mal visibles</td>\n          </tr>\n          <tr>\n            <td><strong>PIO</strong></td>\n            <td>Très élevée <span class=\"kw-alerte\">&gt; 30 mmHg</span> ⭐ — sensation de <strong>« bille de bois »</strong> à la palpation bidigitale à travers la paupière supérieure</td>\n          </tr>\n          <tr>\n            <td><strong>Chambre antérieure</strong></td>\n            <td><strong>Peu profonde</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Gonioscopie</strong></td>\n            <td>Angle iridocornéen <strong>fermé</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Œil adelphe (autre œil)</strong></td>\n            <td>Chambre antérieure peu profonde + angle iridocornéen étroit (⚠️ <strong>ne pas dilater</strong> la pupille pour l'examen)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique.</strong> La triade <em><span class=\"kw-clinique\">nausées</span> + <span class=\"kw-clinique\">vomissements</span> + douleur</em> peut orienter à tort vers une <span class=\"kw-alerte\">urgence</span> digestive ou neurologique. Toute <strong>douleur oculaire intense brutale</strong>, surtout chez un sujet âgé, justifie un <strong>examen ophtalmologique en urgence</strong> avec mesure de la PIO.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision</em></p>","frequence":1},{"id":"84-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les facteurs de risque et les facteurs déclenchants d’une crise de glaucome aigu par fermeture de l’angle","contenu":"<p>La crise aiguë par fermeture de l'angle survient sur un <strong><span class=\"kw-def\">terrain</span> prédisposé</strong> (angle iridocornéen étroit) soumis à un <strong>facteur déclenchant</strong> provoquant la mydriase et le blocage trabéculaire.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Facteurs de risque</span> (terrain) ⭐⭐</h4>\n      <table >\n        <thead><tr><th>Facteur</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Risque augmente avec l'âge</td>\n          </tr>\n          <tr>\n            <td><strong>Sexe féminin</strong></td>\n            <td>Risque plus élevé chez <span class=\"kw-clinique\">les</span> <strong>femmes</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Ethnie asiatique</strong></td>\n            <td><span class=\"kw-def\">Prévalence</span> majorée en <strong>Asie</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Cataracte</strong></td>\n            <td>Augmentation du volume cristallinien → diminution de la chambre antérieure</td>\n          </tr>\n          <tr>\n            <td><strong>Hypermétropie</strong> ⭐</td>\n            <td><strong>Globe oculaire de petite taille</strong> → angle iridocornéen <strong>étroit</strong> physiologiquement</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Facteurs déclenchants — mydriase ⭐⭐</h4>\n      <p>Toute <strong>dilatation pupillaire</strong> peut déclencher la crise.</p>\n\n      <table >\n        <thead><tr><th>Type</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Physiologique</strong></td>\n            <td>\n              Obscurité (cinéma, conduite nocturne) ; <br>\n              Stress, émotion ; <br>\n              Exercice physique <em>(stimulation du système sympathique)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pharmacologique : examen ophtalmo</strong></td>\n            <td>\n              <strong>Mydriatique</strong> pour examen du <span class=\"kw-imagerie\">fond d'œil</span> — <span class=\"kw-alerte\">à proscrire</span> sur un <span class=\"kw-def\">terrain</span> à risque\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments mydriatiques</strong> ⭐</td>\n            <td>\n              <span class=\"kw-ttt\">Anticholinergiques</span> (<span class=\"kw-ttt\">atropine</span> et dérivés) ; <br>\n              <span class=\"kw-ttt\">Antihistaminiques H1</span> (<span class=\"kw-chiffre\">1ère génération</span>) ; <br>\n              <span class=\"kw-ttt\">Antidépresseurs</span> (tricycliques, <span class=\"kw-ttt\">IMAO</span>, <span class=\"kw-ttt\">ISRS</span>) ; <br>\n              <span class=\"kw-ttt\">Neuroleptiques</span> avec effet anticholinergique (phénothiazines) ; <br>\n              <span class=\"kw-ttt\">Antiparkinsoniens, antispasmodiques</span> anticholinergiques ; <br>\n              <span class=\"kw-ttt\">Sympathomimétiques</span> (vasoconstricteurs, épinéphrine) ; <br>\n              <span class=\"kw-ttt\">Anxiolytiques</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Physiopathologie</span> (rappel)</h4>\n      <ol>\n        <li><strong>Bloc pupillaire :</strong> en mydriase, l'iris s'accole contre le cristallin → gêne à l'écoulement de l'humeur aqueuse de la chambre postérieure vers la chambre antérieure.</li>\n        <li><strong>Hyperpression en chambre postérieure</strong> &gt; chambre antérieure.</li>\n        <li><strong>Bloc trabéculaire :</strong> l'iris est bombé en avant contre le trabéculum.</li>\n        <li><strong>Fermeture de l'angle</strong> → élévation brutale de la PIO.</li>\n      </ol>\n\n      <div class=\"callout callout-warn\">\n        <strong>CI médicamenteuses du glaucome par fermeture de l'angle ⭐.</strong> <span class=\"kw-ci\">Tous les médicaments mydriatiques sont contre-indiqués</span> chez un patient à risque (angle étroit non opéré). Toujours vérifier <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">RCP</span>. Ces CI <strong>disparaissent</strong> après <strong>iridotomie au <span class=\"kw-ttt\">laser</span></strong> et/ou <strong><span class=\"kw-ttt\">chirurgie</span> filtrante</strong> ✅.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments · 85 — Troubles de la réfraction</em></p>","frequence":2},{"id":"84-14","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir qu’une crise de glaucome aigu par fermeture de l’angle est une urgence menaçant le pronostic visuel","contenu":"<p>La crise aiguë par fermeture de l'angle est une <span class=\"kw-alerte\">urgence ophtalmologique absolue</span> : sans traitement, elle entraîne la <strong>destruction irréversible des fibres optiques papillaires</strong> et la <strong>cécité définitive</strong> de l'œil atteint.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pourquoi est-ce une <span class=\"kw-alerte\">urgence</span> ?</h4>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>PIO &gt;<span class=\"kw-chiffre\"> 30 mmHg</span> brutale et prolongée</strong></td>\n            <td>Souffrance <span class=\"kw-etio\">ischémique</span> du nerf optique en quelques heures</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Œdème</span> cornéen</strong></td>\n            <td>BAV majeure, opacification persistante si retardé</td>\n          </tr>\n          <tr>\n            <td><strong>Risque sur l'œil adelphe</strong></td>\n            <td><span class=\"kw-def\">Terrain</span> prédisposant des 2 côtés → risque de crise bilatérale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span> sans traitement</strong></td>\n            <td><span class=\"kw-alerte\">Destruction irréversible des fibres optiques</span> → cécité définitive</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Conduite à tenir immédiate ⭐</h4>\n      <ol>\n        <li><strong>Orientation immédiate</strong> en milieu ophtalmologique (souvent <strong><span class=\"kw-alerte\">hospitalisation</span> 🏥</strong>).</li>\n        <li>Reconnaître <span class=\"kw-clinique\">les</span> signes : <span class=\"kw-clinique\">œil rouge</span> + <span class=\"kw-clinique\">douloureux</span> + <span class=\"kw-clinique\">BAV brutale</span> ± <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span>.</li>\n        <li>Mesurer la PIO (« bille de bois » à la palpation).</li>\n        <li><strong>NE PAS dilater</strong> la pupille (mydriatique = aggravation).</li>\n        <li><strong>NE PAS prescrire</strong> de médicament mydriatique.</li>\n        <li>Démarrer rapidement le traitement hypotonisant local + général.</li>\n      </ol>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Diagnostics à éliminer en <span class=\"kw-alerte\">urgence</span></h4>\n      <ul>\n        <li><strong>Kératite</strong> (œil rouge + douloureux + BAV).</li>\n        <li><strong>Uvéite antérieure</strong>.</li>\n        <li><strong>Endophtalmie</strong> (post-chirurgicale).</li>\n        <li><strong>Sclérite</strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Pronostic</span>.</strong> La <em>rapidité</em> de la prise en charge conditionne directement le pronostic visuel. Une CAFA traitée dans <span class=\"kw-clinique\">les</span> <strong>premières heures</strong> peut récupérer ad integrum ; une crise négligée <span class=\"kw-chiffre\">24-48h</span> évolue vers la cécité.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision</em></p>","frequence":1},{"id":"84-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge en urgence du glaucome aigu par fermeture de l’angle","contenu":"<p>La PEC de la CAFA repose sur un <strong>protocole hospitalier en 3 temps</strong> : baisser la PIO en <span class=\"kw-alerte\">urgence</span>, lever le bloc pupillaire, puis sécuriser définitivement par <strong>iridotomie au <span class=\"kw-ttt\">laser</span> YAG bilatérale</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Protocole en 3 temps ⭐⭐</h4>\n      <table >\n        <thead><tr><th>Temps</th><th>Objectif</th><th>Moyens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1er temps</strong></td>\n            <td>Baisser la PIO en <span class=\"kw-alerte\">urgence</span></td>\n            <td>\n              <strong>Hypotonisants en collyre :</strong><br>\n              • <span class=\"kw-ttt\">Analogue de prostaglandine</span><br>\n              • <span class=\"kw-ttt\">α-mimétiques</span> (apraclonidine)<br>\n              • <span class=\"kw-ttt\">Acétazolamide collyre</span><br>\n              • <span class=\"kw-ttt\">β-bloquants collyre</span><br><br>\n              <strong>Hypotonisants par voie générale :</strong><br>\n              • <span class=\"kw-ttt\">Acétazolamide per os ou IV</span><br>\n              • <span class=\"kw-ttt\">Mannitol IV</span> <em>(<span class=\"kw-clinique\">déshydratation</span> du globe)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2nd temps</strong></td>\n            <td>Lever le bloc pupillaire</td>\n            <td>\n              <strong>Collyre myotique sur <span class=\"kw-clinique\">les</span> 2 yeux :</strong><br>\n              <span class=\"kw-ttt\">Pilocarpine collyre</span> → ramène la pupille en <strong>myosis</strong><br>\n              <em>(facilite l'écoulement de l'humeur aqueuse de la CP vers la CA)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3ème temps</strong></td>\n            <td>Sécuriser durablement</td>\n            <td>\n              <strong>Iridotomie périphérique BILATÉRALE au <span class=\"kw-ttt\">laser</span> YAG</strong> ⭐<br>\n              Réalisée <em>une fois la PIO normalisée et l'<span class=\"kw-clinique\">œdème</span> de cornée réduit</em><br>\n              <strong>Bilatérale</strong> car l'œil adelphe a le même <span class=\"kw-def\">terrain</span> prédisposant\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">En cas d'échec du traitement médical</h4>\n      <ul>\n        <li><strong>Trabéculectomie</strong> (procédure de référence — selon le PU, on troue aussi l'iris).</li>\n        <li><strong><span class=\"kw-ttt\">Chirurgie</span> de la cataracte</strong> (si sujet âgé avec opacité cristallinienne) — éloigne l'iris du trabéculum.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Après iridotomie ou <span class=\"kw-ttt\">chirurgie</span> de la cataracte.</strong> Le risque de fermeture de l'angle lors d'une dilatation pupillaire <strong>disparaît</strong> : <span class=\"kw-clinique\">les</span> agents pharmacologiques mydriatiques <strong>ne sont plus <span class=\"kw-ci\">contre-indiqués</span></strong> ✅.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Mesures associées</h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Antalgiques</span></strong> (douleur intense).</li>\n        <li><strong>Antiémétiques</strong> (<span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span>).</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> horaire</strong> de la PIO en <span class=\"kw-alerte\">hospitalisation</span>.</li>\n        <li><strong>Bilan ophtalmologique complet</strong> une fois la crise jugulée (<span class=\"kw-imagerie\">FO</span>, <span class=\"kw-imagerie\">OCT</span>, <span class=\"kw-bio\">CV</span>) pour évaluer <span class=\"kw-clinique\">les</span> séquelles glaucomateuses.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Le séquençage <em>hypotonisants → myotique → iridotomie YAG</em> est <strong>non négociable</strong> : on ne fait pas le <span class=\"kw-ttt\">laser</span> sur une cornée œdématiée. L'<strong>iridotomie bilatérale</strong> est la mesure préventive définitive sur <span class=\"kw-clinique\">les</span> 2 yeux.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> la <span class=\"kw-alerte\">crise aiguë par fermeture de l'angle (CAFA)</span> est une <span class=\"kw-alerte\">urgence ophtalmologique menaçant le pronostic visuel</span>.<br><strong>Fenêtre :</strong> <span class=\"kw-alerte\">destruction irréversible des fibres optiques papillaires</span> en l'absence de traitement → abaisser la PIO sans délai.<br><strong>1er geste :</strong> baisser rapidement la <span class=\"kw-chiffre\">PIO</span> par <span class=\"kw-ttt\">hypotonisants en collyre</span> + <span class=\"kw-ttt\">voie générale</span> (<span class=\"kw-ttt\">acétazolamide</span>, <span class=\"kw-ttt\">mannitol IV</span>).<br><strong>À l'inverse :</strong> le <span class=\"kw-def\">glaucome primitif à angle ouvert (GPAO)</span> n'est <strong>pas une <span class=\"kw-alerte\">urgence</span></strong> (<span class=\"kw-clinique\">évolution</span> lente, initialement asymptomatique, prise en charge programmée).</p>","hospit":"<p><strong>CAFA :</strong> traitement en <span class=\"kw-alerte\">urgence</span>, nécessitant souvent une <span class=\"kw-ttt\">hospitalisation</span> pour normaliser la PIO.<br><strong>GPAO :</strong> prise en charge <span class=\"kw-ttt\">ambulatoire</span> en consultation d'ophtalmologie, traitement <span class=\"kw-ttt\">médical</span> en <span class=\"kw-chiffre\">première ligne</span>.<br><strong><span class=\"kw-def\">Dépistage</span> :</strong> <span class=\"kw-ttt\">mesure de la PIO + fond d'œil</span> systématique chez tout patient de <span class=\"kw-chiffre\">&gt; 40 ans</span> et/ou en présence de <span class=\"kw-def\">facteurs de risque</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Œil rouge et douloureux</span> avec <span class=\"kw-clinique\">douleurs profondes oculaires et péri-oculaires</span> irradiant dans le territoire du <span class=\"kw-clinique\">trijumeau</span> (CAFA)</li><li><span class=\"kw-alerte\">BAV brutale et importante</span>, tableau d'installation <span class=\"kw-clinique\">brutal et bruyant</span></li><li><span class=\"kw-clinique\">Nausées et vomissements</span> souvent associés (peuvent égarer le diagnostic)</li><li><span class=\"kw-clinique\">Semi-mydriase aréactive</span> à la lumière (traduit le bloc pupillaire)</li><li><span class=\"kw-alerte\">PIO &gt; 30 mmHg</span> : <span class=\"kw-clinique\">sensation de « bille de bois »</span> à la palpation bidigitale</li><li><span class=\"kw-clinique\">Œdème cornéen</span>, cercle périkératique, <span class=\"kw-clinique\">chambre antérieure peu profonde</span>, angle fermé en gonioscopie</li><li>GPAO évolué : <span class=\"kw-alerte\">champ visuel tubulaire</span> annonçant la <span class=\"kw-alerte\">cécité</span> (handicap lié à l'altération du champ visuel, jamais à l'acuité)</li></ul>","principes":"<p><strong>Cible unique :</strong> abaisser la <span class=\"kw-chiffre\">PIO</span>, <span class=\"kw-def\">seul facteur de risque accessible au traitement</span> — valable pour le GPAO à PIO élevée comme à PIO normale.</p><p><strong>GPAO — <span class=\"kw-chiffre\">1ère intention</span></strong></p><p>augmentation de l'élimination (prostaglandines) ou diminution de la sécrétion (β-bloquant) d'humeur aqueuse</p><ul><li><span class=\"kw-ttt\">Monothérapie</span> : collyre <span class=\"kw-ttt\">analogue de prostaglandines</span> (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>outte le soir) ou collyre <span class=\"kw-ttt\">β-bloquant</span></li><li><span class=\"kw-ci\">β-bloquants contre-indiqués</span> si <span class=\"kw-ci\">asthme</span>, <span class=\"kw-ci\">insuffisance cardiaque</span>, <span class=\"kw-ci\">troubles de conduction</span>, <span class=\"kw-ci\">phénomène de Raynaud</span></li><li>Switch d'hypotonisant possible avant de passer à une bithérapie</li></ul><p><strong>GPAO — 2nde intention</strong></p><ul><li><span class=\"kw-ttt\">Bithérapie</span> combinant <span class=\"kw-clinique\">les</span> 4 classes disponibles (toutes les associations sont possibles)</li><li>Diminution de la sécrétion : <span class=\"kw-ttt\">agonistes α2-adrénergiques</span> (brimonidine), <span class=\"kw-ttt\">inhibiteurs de l'anhydrase carbonique</span> (collyre ou per os)</li><li>Ne pas dépasser en règle une <span class=\"kw-chiffre\">trithérapie</span></li></ul><p><strong>GPAO — 3ème intention</strong></p><p>recours plus rapide si glaucome évolué, patient jeune, échec/<span class=\"kw-ci\">intolérance</span> des collyres ou cataracte associée</p><ul><li><span class=\"kw-ttt\">Chirurgie filtrante par trabéculectomie</span> = procédure de référence (ablation sectorielle limitée du trabéculum)</li><li>Variante : <span class=\"kw-ttt\">sclérectomie profonde non perforante</span></li><li><span class=\"kw-ttt\">Trabéculoplastie au laser Argon</span> : effet modeste et non durable, indications limitées</li></ul><p><strong>CAFA — traitement en <span class=\"kw-alerte\">urgence</span> (par temps)</strong></p><p>après iridotomie ou <span class=\"kw-ttt\">chirurgie</span> de la cataracte, <span class=\"kw-clinique\">les</span> mydriatiques ne sont plus <span class=\"kw-ci\">contre-indiqués</span></p><ul><li><strong>1er temps :</strong> baisse rapide de la PIO — <span class=\"kw-ttt\">hypotonisants en collyre</span> (prostaglandine, α-mimétiques, acétazolamide, β-bloquant) + voie générale (<span class=\"kw-ttt\">acétazolamide per os/IV</span>, <span class=\"kw-ttt\">mannitol IV</span>)</li><li><strong>2nd temps :</strong> <span class=\"kw-ttt\">collyre myotique (pilocarpine)</span> sur <span class=\"kw-clinique\">les</span> 2 yeux pour ramener la pupille en <span class=\"kw-clinique\">myosis</span></li><li><strong>3ème temps :</strong> <span class=\"kw-ttt\">iridotomie périphérique bilatérale au laser YAG</span>, une fois la <span class=\"kw-chiffre\">PIO normalisée</span> et l'<span class=\"kw-clinique\">œdème cornéen réduit</span></li><li><strong>Si échec :</strong> <span class=\"kw-ttt\">trabéculectomie</span> et/ou <span class=\"kw-ttt\">chirurgie de la cataracte</span></li></ul><p><strong><span class=\"kw-ci\">Contre-indications</span> médicamenteuses</strong></p><ul><li><span class=\"kw-def\">GPAO</span> : <span class=\"kw-ci\">corticoïdes</span> = seule classe pouvant élever la PIO (surtout en voie locale péri-/intra-oculaire)</li><li><span class=\"kw-def\">Fermeture de l'angle</span> : <span class=\"kw-ci\">tous les mydriatiques contre-indiqués</span> — <span class=\"kw-ci\">anticholinergiques (atropine)</span>, <span class=\"kw-ci\">antihistaminiques H1</span>, <span class=\"kw-ci\">antidépresseurs</span>, <span class=\"kw-ci\">vasoconstricteurs</span>, <span class=\"kw-ci\">antiparkinsoniens</span></li></ul>","suivi":"<p><strong>GPAO :</strong> traitement hypotonisant <span class=\"kw-ttt\">prescrit à vie</span>, à <span class=\"kw-ci\">ne jamais</span> interrompre inopinément.<br><strong>Rythme :</strong> évaluation <span class=\"kw-chiffre\">tous les 6 mois</span> — <span class=\"kw-bio\">PIO</span>, aspect de la <span class=\"kw-clinique\">tête du nerf optique</span> (<span class=\"kw-imagerie\">FO</span>, <span class=\"kw-imagerie\">OCT</span>) et <span class=\"kw-imagerie\">champ visuel (PSA de Humphrey)</span>.<br><strong>Adaptation :</strong> traitement modifié en cas d'<span class=\"kw-alerte\">aggravation trop rapide</span> du champ visuel et/ou de l'excavation papillaire.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Œil rouge, douloureux + BAV brutale ± nausées/vomissements ? — Tableau brutal et bruyant","detail":"<h4>CAT — Glaucome : œil rouge aigu <span class=\"kw-bio\">vs</span> glaucome chronique — Orienter selon la présentation clinique puis la gonioscopie</h4>","branches":[{"to":"q-gonio","label":"Oui","color":"red"},{"to":"q-bilan","label":"Non — œil blanc, indolore","color":"green"}]},{"id":"q-gonio","kind":"decision","label":"Gonioscopie : angle iridocornéen fermé ? — PIO > 30 mmHg, semi-mydriase aréactive, œdème cornéen","branches":[{"to":"t-cafa","label":"Angle fermé","color":"red"},{"to":"t-neovasc","label":"Angle ouvert + rubéose irienne","color":"amber"}]},{"id":"t-cafa","kind":"terminal","label":"Crise aiguë par fermeture de l'angle — URGENCE","color":"red","detail":"<h4>Délai</h4><ul><li><span class=\"kw-alerte\">Urgence ophtalmologique</span> menaçant le <span class=\"kw-def\">pronostic</span> visuel : <span class=\"kw-alerte\">destruction irréversible des fibres optiques</span> sans traitement</li><li>Traitement en <span class=\"kw-alerte\">urgence</span>, <span class=\"kw-ttt\">hospitalisation</span> souvent nécessaire</li></ul><h4>Traitement</h4><ul><li><strong>1.</strong> baisse rapide de la PIO : <span class=\"kw-ttt\">hypotonisants en collyre</span> + <span class=\"kw-ttt\">acétazolamide per os/IV</span>, <span class=\"kw-ttt\">mannitol IV</span></li><li><strong>2.</strong> <span class=\"kw-ttt\">pilocarpine</span> (myosis) sur <span class=\"kw-clinique\">les</span> 2 yeux</li><li><strong>3.</strong> <span class=\"kw-ttt\">iridotomie bilatérale au laser YAG</span> après <span class=\"kw-chiffre\">normalisation de la PIO</span> et régression de l'<span class=\"kw-clinique\">œdème</span> cornéen</li><li>Si échec : <span class=\"kw-ttt\">trabéculectomie</span> ± <span class=\"kw-ttt\">chirurgie de la cataracte</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ci\">Ne pas dilater la pupille de l'œil adelphe</span> ; <span class=\"kw-ci\">mydriatiques contre-indiqués</span> jusqu'à l'iridotomie</li></ul>"},{"id":"t-neovasc","kind":"terminal","label":"Glaucome néovasculaire — Œil rouge douloureux avec BAV mais angle ouvert","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Rubéose irienne</span> (néovaisseaux iriens) à la lampe à fente, <span class=\"kw-clinique\">hyphéma</span> possible</li><li>Étiologies : <span class=\"kw-etio\">diabète (rétinopathie proliférante)</span>, <span class=\"kw-etio\">OVCR ischémique</span>, <span class=\"kw-etio\">OACR</span></li></ul><h4>Traitement</h4><ul><li>Baisse de la PIO (<span class=\"kw-ttt\">hypotonisant local + acétazolamide</span>) puis <span class=\"kw-ttt\">photocoagulation panrétinienne au laser</span> en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">anti-VEGF</span> en adjuvant</li><li><span class=\"kw-ci\">Iridotomie d'aucune utilité</span> (pas de bloc pupillaire)</li></ul>"},{"id":"q-bilan","kind":"decision","label":"PIO > 21 mmHg et/ou excavation papillaire suspecte ? — Œil blanc indolore — découverte fortuite ou dépistage > 40 ans","branches":[{"to":"q-neuro","label":"Oui","color":"amber"},{"to":"t-normal","label":"Non","color":"green"}]},{"id":"q-neuro","kind":"decision","label":"Champ visuel (PSA) + OCT : neuropathie optique glaucomateuse ? — Anomalies de la papille + déficits campimétriques (scotome de Bjerrum, ressaut nasal)","branches":[{"to":"t-gpao","label":"Oui","color":"amber"},{"to":"t-hto","label":"Non — PIO élevée isolée","color":"amber"}]},{"id":"t-gpao","kind":"terminal","label":"GPAO confirmé — traitement hypotonisant à vie","color":"amber","detail":"<h4>Traitement</h4><ul><li><strong><span class=\"kw-chiffre\">1ère intention</span> :</strong> monothérapie — <span class=\"kw-ttt\">prostaglandine</span> ou <span class=\"kw-ttt\">β-bloquant</span> en collyre</li><li><strong>2nde intention :</strong> <span class=\"kw-ttt\">bithérapie</span> (4 classes ; ajout <span class=\"kw-ttt\">α2-agonistes</span>, <span class=\"kw-ttt\">inhibiteurs de l'anhydrase carbonique</span>)</li><li><strong>3ème intention :</strong> <span class=\"kw-ttt\">chirurgie filtrante (trabéculectomie)</span>, <span class=\"kw-ttt\">trabéculoplastie laser Argon</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-chiffre\">Tous les 6 mois</span> : <span class=\"kw-bio\">PIO</span>, <span class=\"kw-imagerie\">FO / OCT</span>, <span class=\"kw-imagerie\">champ visuel</span> — traitement à vie</li></ul>"},{"id":"t-hto","kind":"terminal","label":"Hypertonie oculaire isolée — surveillance — PIO > 21 mmHg + angle ouvert + absence de neuropathie","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Pas de traitement systématique</span>, mais <span class=\"kw-ttt\">surveillance</span> car reste un <span class=\"kw-def\">facteur de risque</span> de GPAO</li><li>Touche <span class=\"kw-chiffre\">10× plus</span> d'individus que le glaucome</li></ul>"},{"id":"t-normal","kind":"terminal","label":"Pas d'argument pour un glaucome — Examen normal","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Dépistage simple</span> par mesure de la PIO + <span class=\"kw-imagerie\">fond d'œil</span> chez tout patient de <span class=\"kw-chiffre\">&gt; 40 ans</span> et/ou avec <span class=\"kw-def\">facteurs de risque</span></li></ul>"}]},"cards":[{"i":"022db6f1ac86","n":84,"o":"84-1","u":"Définition","t":"Connaître la définition du glaucome primitif à angle ouvert","q":"Quelles sont les deux atteintes caractéristiques du glaucome primitif à angle ouvert (GPAO) ?","a":"<ul><li>Une atteinte <strong>structurelle</strong> : anomalies caractéristiques de la tête du nerf optique (papille optique) comme une diminution de l'anneau neurorétinien et une augmentation du <strong>cup/disc ratio</strong>.</li><li>Une atteinte <strong>fonctionnelle</strong> : altérations du champ visuel pouvant aboutir à la cécité à un stade tardif.</li></ul>"},{"i":"2d2e901b2aaf","n":84,"o":"84-1","u":"Définition","t":"Connaître la définition du glaucome primitif à angle ouvert","q":"Quelle est la définition du glaucome primitif à angle ouvert (GPAO) ?","a":"<p>Le glaucome primitif à angle ouvert (GPAO) est une <strong>neuropathie optique progressive</strong> caractérisée par une <strong>apoptose accélérée des cellules ganglionnaires rétiniennes</strong>, survenant en présence d'un <strong>angle iridocornéen ouvert</strong> et en l'absence d'anomalies oculaires ou générales identifiables.</p>"},{"i":"d6dd3bad5ee3","n":84,"o":"84-1","u":"Définition","t":"Connaître la définition du glaucome primitif à angle ouvert","q":"Quelle est la particularité épidémiologique du glaucome primitif à angle ouvert (GPAO) en Occident et en Afrique, comparativement à l'Asie ?","a":"<p>En <strong>Occident et en Afrique</strong>, le GPAO représente <strong>70-80 %</strong> de l'ensemble des glaucomes. En revanche, en <strong>Asie</strong>, les glaucomes par fermeture de l'angle prédominent.</p>"},{"i":"38df13c74b00","n":84,"o":"84-12","u":"Diagnostic positif","t":"Connaître les signes d’une crise de glaucome aigu par fermeture de l’angle","q":"Comment l'examen ophtalmologique se présente-t-il lors d'une crise aiguë par fermeture de l'angle (CAFA) ?","a":"<p>Lors d'une CAFA, l'examen ophtalmologique révèle :</p><ul><li>Une <strong>cornée opaque</strong> avec un œdème cornéen rendant les reliefs de l'iris mal visibles.</li><li>Une <strong>pression intra-oculaire (PIO) très élevée</strong> (supérieure à <strong>30 mmHg</strong>), donnant une sensation de « bille de bois » à la palpation bidigitale.</li><li>Une <strong>chambre antérieure peu profonde</strong>.</li><li>Une <strong>gonioscopie</strong> montrant un <strong>angle iridocornéen fermé</strong>.</li><li>L'<strong>œil adelphe</strong> présente souvent une chambre antérieure peu profonde et un angle iridocornéen étroit, justifiant de <strong>ne pas dilater la pupille</strong> pour son examen.</li></ul>"},{"i":"9ea68fb12dd9","n":84,"o":"84-12","u":"Diagnostic positif","t":"Connaître les signes d’une crise de glaucome aigu par fermeture de l’angle","q":"Quels sont les signes associés fréquents et les pièges diagnostiques liés à une crise aiguë par fermeture de l'angle (CAFA) ?","a":"<p>Les signes associés fréquents d'une CAFA sont des <strong>nausées et vomissements</strong>, qui peuvent orienter à tort vers une urgence digestive ou neurologique. Un autre signe est une <strong>pupille en semi-mydriase aréflexique</strong>, témoin du bloc pupillaire. Toute douleur oculaire intense et brutale, surtout chez un sujet âgé, doit faire rechercher une CAFA.</p>"},{"i":"a973526540b9","n":84,"o":"84-12","u":"Diagnostic positif","t":"Connaître les signes d’une crise de glaucome aigu par fermeture de l’angle","q":"Quelle est la triade évocatrice d'une crise aiguë par fermeture de l'angle (CAFA) ?","a":"<p>La triade évocatrice d'une CAFA comprend :</p><ul><li>Un <strong>œil rouge</strong> (hyperhémie conjonctivale avec cercle périkératique).</li><li>Un <strong>œil douloureux</strong> (douleurs profondes, intenses, oculaires et péri-oculaires, irradiant dans le territoire du trijumeau).</li><li>Une <strong>baisse d'acuité visuelle brutale</strong>, souvent importante et dépendant de l'œdème cornéen.</li></ul>"},{"i":"412315ae9c54","n":84,"o":"84-14","u":"Identifier une urgence","t":"Savoir qu’une crise de glaucome aigu par fermeture de l’angle est une urgence menaçant le pronostic visuel","q":"Quels sont les signes cliniques clés d'une crise aiguë de glaucome par fermeture de l'angle (CAFA) à reconnaître en urgence ?","a":"<p>Les signes cliniques clés d'une CAFA sont :</p><ul><li>Un <strong>œil rouge</strong>.</li><li>Une <strong>douleur oculaire intense</strong>.</li><li>Une <strong>baisse d'acuité visuelle (BAV) brutale</strong>.</li><li>Fréquemment associée à des <strong>nausées et vomissements</strong>.</li><li>À la palpation, l'œil est décrit comme une « <strong>bille de bois</strong> », témoignant d'une PIO très élevée.</li><li>Un <strong>œdème cornéen</strong> peut être présent.</li></ul>"},{"i":"83a590cd633c","n":84,"o":"84-14","u":"Identifier une urgence","t":"Savoir qu’une crise de glaucome aigu par fermeture de l’angle est une urgence menaçant le pronostic visuel","q":"Quel est le pronostic visuel d'une crise aiguë de glaucome par fermeture de l'angle (CAFA) en fonction de la rapidité de la prise en charge ?","a":"<p>La rapidité de la prise en charge est <strong>conditionne directement le pronostic visuel</strong> :</p><ul><li>Une CAFA traitée dans les <strong>premières heures</strong> peut récupérer <em>ad integrum</em>.</li><li>Une crise négligée pendant <strong>24 à 48 heures</strong> évolue vers la <strong>cécité définitive</strong> en raison de la destruction irréversible des fibres optiques.</li></ul>"},{"i":"9e16b88581a0","n":84,"o":"84-14","u":"Identifier une urgence","t":"Savoir qu’une crise de glaucome aigu par fermeture de l’angle est une urgence menaçant le pronostic visuel","q":"Quelle conduite à tenir immédiate en cas de suspicion de crise aiguë de glaucome par fermeture de l'angle (CAFA) ?","a":"<p>En cas de suspicion de CAFA, la conduite à tenir immédiate est :</p><ul><li><strong>Orientation immédiate en milieu ophtalmologique</strong> (souvent avec hospitalisation).</li><li><strong>NE PAS dilater la pupille</strong> : les médicaments mydriatiques sont formellement contre-indiqués et aggraveraient la situation.</li><li>Démarrer rapidement un <strong>traitement hypotonisant local et général</strong>.</li></ul>"},{"i":"c429bf4d6d41","n":84,"o":"84-14","u":"Identifier une urgence","t":"Savoir qu’une crise de glaucome aigu par fermeture de l’angle est une urgence menaçant le pronostic visuel","q":"Quels sont les diagnostics ophtalmologiques à éliminer en urgence devant un tableau pseudo-CAFA (œil rouge, douloureux, BAV brutale) ?","a":"<p>Devant un œil rouge, douloureux et une BAV brutale, il faut éliminer en urgence les diagnostics suivants :</p><ul><li>La <strong>kératite</strong>.</li><li>L'<strong>uvéite antérieure</strong>.</li><li>L'<strong>endophtalmie</strong> (notamment en post-chirurgical).</li><li>La <strong>sclérite</strong>.</li></ul>"},{"i":"e22dcec7124d","n":84,"o":"84-14","u":"Identifier une urgence","t":"Savoir qu’une crise de glaucome aigu par fermeture de l’angle est une urgence menaçant le pronostic visuel","q":"Pourquoi la crise aiguë du glaucome par fermeture de l'angle (CAFA) est-elle une urgence ophtalmologique absolue ?","a":"<p>La CAFA est une urgence absolue car, sans traitement, elle entraîne une augmentation brutale et prolongée de la <strong>Pression Intraoculaire (PIO)</strong>, supérieure à 30 mmHg, conduisant à une <strong>souffrance ischémique du nerf optique</strong>. Cela provoque la <strong>destruction irréversible des fibres optiques papillaires</strong> et la <strong>cécité définitive</strong> de l'œil atteint en quelques heures.</p>"},{"i":"2408eb67fc1e","n":84,"o":"84-3","u":"Définition","t":"Connaître les facteurs de risque du glaucome primitif à angle ouvert","q":"Quelle est l'importance de l'hypertonie oculaire comme facteur de risque du glaucome primitif à angle ouvert (GPAO) ?","a":"<p>L'<strong>hypertonie oculaire</strong> (Pression Intraoculaire > 20-22 mmHg) est un facteur de risque important du GPAO. C'est le <strong>seul facteur de risque modifiable</strong> et donc la cible thérapeutique exclusive. Cependant, sa présence n'est ni nécessaire ni suffisante pour porter le diagnostic de GPAO.</p>"},{"i":"a60461477ec4","n":84,"o":"84-3","u":"Définition","t":"Connaître les facteurs de risque du glaucome primitif à angle ouvert","q":"Quels sont les facteurs de risque du glaucome primitif à angle ouvert (GPAO) les plus solidement établis ?","a":"<p>Les facteurs de risque du GPAO les plus solidement établis sont :</p><ul><li>L'<strong>âge élevé</strong></li><li>L'<strong>hypertonie oculaire</strong></li><li>Les <strong>antécédents familiaux directs</strong></li><li>L'<strong>ethnie mélanoderme</strong></li><li>La <strong>myopie</strong> (toute intensité)</li></ul>"},{"i":"fc1b8aacefcf","n":84,"o":"84-3","u":"Définition","t":"Connaître les facteurs de risque du glaucome primitif à angle ouvert","q":"Quels sont les facteurs de risque du glaucome primitif à angle ouvert (GPAO) moins bien étayés ?","a":"<p>Le <strong>diabète</strong> et les <strong>maladies cardiovasculaires</strong> sont des facteurs de risque du GPAO décrits mais moins bien étayés que les précédents.</p>"},{"i":"42b193cb76df","n":84,"o":"84-7","u":"Prise en charge","t":"Savoir que le traitement du glaucome primitif à angle ouvert est la réduction de la PIO","q":"Quel est l'objectif thérapeutique principal du glaucome primitif à angle ouvert (GPAO) ?","a":"<p>L'objectif thérapeutique unique du GPAO est de <strong>réduire la pression intraoculaire (PIO)</strong> afin de ralentir la dégénérescence des fibres optiques.</p>"},{"i":"715d2b2c1665","n":84,"o":"84-7","u":"Prise en charge","t":"Savoir que le traitement du glaucome primitif à angle ouvert est la réduction de la PIO","q":"Quelle est la principale cause de handicap chez un patient atteint de glaucome ?","a":"<p>Le handicap chez le patient glaucomateux est causé par l'<strong>altération du champ visuel</strong>, et non par une baisse de l'acuité visuelle. La grille d'invalidité pertinente est donc celle basée sur le champ visuel.</p>"},{"i":"b23435db512d","n":84,"o":"84-7","u":"Prise en charge","t":"Savoir que le traitement du glaucome primitif à angle ouvert est la réduction de la PIO","q":"Comment doit être suivi un patient atteint de glaucome primitif à angle ouvert (GPAO) ?","a":"<p>Le suivi du GPAO doit être réalisé <strong>tous les 6 mois</strong> et comprend :</p><ul><li>La mesure de la <strong>PIO</strong>.</li><li>L'évaluation de l'aspect de la <strong>tête du nerf optique</strong> (fond d'œil, OCT).</li><li>La mesure du <strong>champ visuel</strong>.</li></ul><p>Le traitement est adapté ou modifié en cas d'aggravation rapide des altérations.</p>"},{"i":"c26f0591d693","n":84,"o":"84-7","u":"Prise en charge","t":"Savoir que le traitement du glaucome primitif à angle ouvert est la réduction de la PIO","q":"Quelle est la hiérarchie thérapeutique usuelle pour le traitement du glaucome primitif à angle ouvert (GPAO) ?","a":"<ul><li><strong>1ère intention :</strong> Monothérapie en collyre (analogue de prostaglandine OU β-bloquant).</li><li><strong>2ème intention :</strong> Bithérapie combinant les quatre classes disponibles.</li><li><strong>3ème intention :</strong> Chirurgie filtrante (trabéculectomie de référence) ou sclérectomie profonde.</li><li><strong>Option intermédiaire :</strong> Trabéculoplastie au laser Argon (effet modeste et peu durable).</li></ul>"},{"i":"fe29c50a0f87","n":84,"o":"84-7","u":"Prise en charge","t":"Savoir que le traitement du glaucome primitif à angle ouvert est la réduction de la PIO","q":"Quelle est la durée du traitement hypotonisant dans le glaucome primitif à angle ouvert (GPAO) ?","a":"<p>Le traitement hypotonisant du GPAO doit être suivi <strong>à vie</strong> et ne doit pas être interrompu inopinément.</p>"}]};